// ── the trace ────────────────────────────────────────────────────────────────

/// Every format that has samples: those of `formats/` and the gallery ones.
fn formats_with_samples() -> Vec<String> {
    let samples_dir = conformance_dir().join("samples");
    let failing = failing_gallery_formats();
    let mut formats = Vec::new();
    for entry in std::fs::read_dir(&samples_dir)
        .expect("samples exists")
        .flatten()
    {
        let name = entry.file_name().into_string().expect("UTF-8");
        if name != "gallery" {
            formats.push(name);
            continue;
        }
        // a directory of samples is the one that has .bin files: the gallery
        // has formats at different depths (security/ssh_public_key, serialization/asn1/asn1_der)
        let mut stack = vec![(entry.path(), String::from("gallery"))];
        while let Some((dir, prefix)) = stack.pop() {
            for child in std::fs::read_dir(&dir).expect("gallery dir").flatten() {
                let child_name = child.file_name().into_string().expect("UTF-8");
                if !child.path().is_dir() {
                    continue;
                }
                let path = format!("{prefix}/{child_name}");
                let has_bins = std::fs::read_dir(child.path())
                    .expect("a directory")
                    .flatten()
                    .any(|f| f.file_name().to_string_lossy().ends_with(".bin"));
                if has_bins {
                    if !failing.contains(&path) {
                        formats.push(path);
                    }
                } else {
                    stack.push((child.path(), path));
                }
            }
        }
    }
    formats.sort();
    formats
}

/// The gallery formats that doe does not read yet (`failing` in
/// `gallery_samples.tsv`, each with its issue), as `gallery/<path>`: they have
/// samples, and no test until they are fixed.
fn failing_gallery_formats() -> Vec<String> {
    let table = std::fs::read_to_string(conformance_dir().join("gallery_samples.tsv"))
        .expect("the table of the gallery");
    table
        .lines()
        .filter_map(|line| {
            let mut cells = line.split('\t');
            let name = cells.next()?;
            (cells.next()? == "failing").then(|| format!("gallery/{name}"))
        })
        .collect()
}

/// The spans of a tree lie in the input, in order, and a node's children that
/// are fields are inside it unless they were placed with `pos:`.
fn check_spans(
    node: &doe::parser::trace::TraceNode,
    input_bits: u64,
    path: &str,
    problems: &mut Vec<String>,
) {
    let here = format!("{path}/{}", node.name);
    if let Some(span) = node.span {
        if span.end < span.start {
            problems.push(format!("{here}: ends before it starts: {span:?}"));
        }
        if !node.processed && span.end > input_bits {
            problems.push(format!("{here}: ends after the input: {span:?}"));
        }
    } else if !node.is_instance {
        problems.push(format!("{here}: a field without a span"));
    }
    for child in &node.children {
        check_spans(child, input_bits, &here, problems);
    }
}

/// A traced parse of every conformance sample gives the value of an untraced
/// one, with spans inside the input, and a byte finds the field it is in.
#[test]
fn tracing_changes_nothing_and_the_spans_are_in_the_input() {
    use doe::parser::{cursor::Cursor, engine::Engine};
    use doe::schema::compiler::Compiler;

    let mut problems = Vec::new();
    let mut traced_nodes = 0usize;
    for format in formats_with_samples() {
        let ksy = definition(&format);
        let include: Vec<PathBuf> = if format.starts_with("gallery/") {
            vec![gallery_dir()]
        } else {
            Vec::new()
        };
        let mut compiler = Compiler::new(include);
        let schema = doe::load_schema_file(&ksy).expect("the schema loads");
        let id = schema.id.clone();
        compiler
            .process_schema(&schema)
            .expect("the schema compiles");
        let engine = Engine::new(&compiler.registry);
        for name in samples(&format) {
            let path = conformance_dir()
                .join("samples")
                .join(&format)
                .join(format!("{name}.bin"));
            let data = std::fs::read(&path).expect("the sample is readable");
            let plain = engine
                .parse_type(&id, &mut Cursor::new(&data))
                .expect("parses");
            let (traced, root) = engine
                .parse_type_traced(&id, &mut Cursor::new(&data))
                .expect("parses with a trace");
            if plain != traced {
                problems.push(format!("{format}/{name}: the trace changed the value"));
            }
            let input_bits = u64::try_from(data.len()).expect("fits") * 8;
            if root.span.map(|span| span.start) != Some(0) {
                problems.push(format!("{format}/{name}: the root does not start at 0"));
            }
            check_spans(
                &root,
                input_bits,
                &format!("{format}/{name}"),
                &mut problems,
            );
            // The byte at the start of the first field is found in it.
            if let Some(first) = root
                .children
                .iter()
                .find(|c| !c.is_instance && c.span.is_some_and(|s| !s.is_empty()))
            {
                let offset = first.span.map_or(0, |span| span.start_byte());
                if root.find_byte(offset).is_none() {
                    problems.push(format!("{format}/{name}: byte {offset} is in no node"));
                }
            }
            let mut count = 0usize;
            let mut stack = vec![&root];
            while let Some(node) = stack.pop() {
                count += 1;
                stack.extend(node.children.iter());
            }
            traced_nodes += count;
        }
    }
    assert!(problems.is_empty(), "\n{}", problems.join("\n"));
    assert!(traced_nodes > 1000, "only {traced_nodes} nodes were traced");
}

/// Parse every conformance sample cut short in several places: it never
/// panics, and a failure has one failed value in the trace and spans in the
/// input, and what was read agrees with the whole parse for the fields before
/// the cut.
#[test]
fn a_truncated_sample_gives_what_was_read_before_the_cut() {
    use doe::parser::{cursor::Cursor, engine::Engine};
    use doe::schema::compiler::Compiler;

    let mut problems = Vec::new();
    let mut failures = 0usize;
    for format in formats_with_samples() {
        let ksy = definition(&format);
        let include: Vec<PathBuf> = if format.starts_with("gallery/") {
            vec![gallery_dir()]
        } else {
            Vec::new()
        };
        let mut compiler = Compiler::new(include);
        let schema = doe::load_schema_file(&ksy).expect("the schema loads");
        let id = schema.id.clone();
        compiler
            .process_schema(&schema)
            .expect("the schema compiles");
        let engine = Engine::new(&compiler.registry);
        for name in samples(&format) {
            let path = conformance_dir()
                .join("samples")
                .join(&format)
                .join(format!("{name}.bin"));
            let data = std::fs::read(&path).expect("the sample is readable");
            let whole = engine
                .parse_type(&id, &mut Cursor::new(&data))
                .expect("parses");
            let mut cuts = vec![
                0,
                1,
                data.len() / 3,
                data.len() / 2,
                data.len().saturating_sub(1),
            ];
            cuts.sort_unstable();
            cuts.dedup();
            for cut in cuts {
                let Some(head) = data.get(..cut) else {
                    continue;
                };
                let label = format!("{format}/{name} cut at {cut}");
                let outcome = engine
                    .parse_type_partial(&id, &mut Cursor::new(head))
                    .expect("something was tried");
                let input_bits = u64::try_from(cut).expect("fits") * 8;
                let mut found = Vec::new();
                let mut stack = vec![&outcome.trace];
                while let Some(node) = stack.pop() {
                    if node.failed {
                        found.push(node.name.clone());
                    }
                    if let Some(span) = node.span
                        && !node.processed
                        && span.end > input_bits
                    {
                        problems.push(format!("{label}: {} ends after the input", node.name));
                    }
                    stack.extend(node.children.iter());
                }
                if outcome.error.is_none() {
                    if !found.is_empty() {
                        problems.push(format!("{label}: it worked, with a failed value"));
                    }
                    if outcome.value.as_ref() != Some(&whole) && cut == data.len() {
                        problems.push(format!("{label}: the whole input gave another value"));
                    }
                } else {
                    failures += 1;
                    if found.len() != 1 {
                        problems.push(format!("{label}: {} failed values, not one", found.len()));
                    }
                    // The fields that were read are those of the whole parse.
                    if let (
                        Some(Value::Struct { fields: got, .. }),
                        Value::Struct { fields: all, .. },
                    ) = (&outcome.value, &whole)
                    {
                        for (field, value) in got {
                            let in_whole = all.iter().find(|(n, _)| n == field);
                            if in_whole.is_none() && !value.is_absent() {
                                problems.push(format!(
                                    "{label}: field {field} is not in the whole parse"
                                ));
                            }
                        }
                    }
                }
            }
        }
    }
    assert!(problems.is_empty(), "\n{}", problems.join("\n"));
    assert!(failures > 50, "only {failures} cut parses failed");
}

// ── imports from memory ──────────────────────────────────────────────────────

/// Put every schema file under `dir` in `files`, by the path it has on disk.
fn read_tree(dir: &Path, files: &mut doe::schema::source::MemorySource) {
    for entry in std::fs::read_dir(dir)
        .expect("the directory is readable")
        .flatten()
    {
        let path = entry.path();
        if path.is_dir() {
            if path.file_name().is_some_and(|name| name != ".git") {
                read_tree(&path, files);
            }
        } else if path
            .extension()
            .is_some_and(|ext| ext == "ksy" || ext == "yaml")
        {
            let text = std::fs::read_to_string(&path).expect("the file is readable");
            files.insert(&path, text);
        }
    }
}

/// Compiling from files held in memory, with the same include paths, gives the
/// same parse of every conformance sample as compiling from the filesystem:
/// the rules of lookup do not depend on where the files are.
#[test]
fn imports_from_memory_give_the_same_result_as_from_files() {
    use doe::parser::{cursor::Cursor, engine::Engine};
    use doe::schema::compiler::Compiler;
    use doe::schema::source::MemorySource;

    let mut files = MemorySource::new();
    read_tree(&conformance_dir().join("formats"), &mut files);
    read_tree(&gallery_dir(), &mut files);
    assert!(
        files.len() > 150,
        "only {} schema files were found",
        files.len()
    );

    let mut parsed = 0usize;
    for format in formats_with_samples() {
        let ksy = definition(&format);
        let include: Vec<PathBuf> = if format.starts_with("gallery/") {
            vec![gallery_dir()]
        } else {
            Vec::new()
        };
        let mut from_disk = Compiler::new(include.clone());
        let schema = doe::load_schema_file(&ksy).expect("the schema loads");
        let id = schema.id.clone();
        from_disk
            .process_schema(&schema)
            .expect("compiles from files");

        let mut from_memory = Compiler::with_source(include, Box::new(files.clone()));
        let schema = from_memory
            .read_schema(&ksy)
            .expect("the schema is in memory");
        from_memory
            .process_schema(&schema)
            .expect("compiles from memory");

        for name in samples(&format) {
            let path = conformance_dir()
                .join("samples")
                .join(&format)
                .join(format!("{name}.bin"));
            let data = std::fs::read(&path).expect("the sample is readable");
            let on_disk = Engine::new(&from_disk.registry)
                .parse_type(&id, &mut Cursor::new(&data))
                .expect("parses");
            let in_memory = Engine::new(&from_memory.registry)
                .parse_type(&id, &mut Cursor::new(&data))
                .expect("parses");
            assert_eq!(on_disk, in_memory, "{format}/{name}");
            parsed += 1;
        }
    }
    assert!(parsed > 40, "only {parsed} samples were compared");
}

// ── positions in the text ────────────────────────────────────────────────────

/// Every schema of the suite, and every definition of the gallery, can be read
/// into a map of where things are written, and the field ids it finds are at
/// the place the text has them.
#[test]
fn every_definition_can_be_mapped() {
    use doe::schema::locate::SchemaMap;

    let mut unmapped = Vec::new();
    let mut checked = 0usize;
    let mut dirs = vec![conformance_dir().join("formats"), gallery_dir()];
    while let Some(dir) = dirs.pop() {
        for entry in std::fs::read_dir(&dir).expect("readable").flatten() {
            let path = entry.path();
            if path.is_dir() {
                if path.file_name().is_some_and(|name| name != ".git") {
                    dirs.push(path);
                }
                continue;
            }
            if !path
                .extension()
                .is_some_and(|ext| ext == "ksy" || ext == "yaml")
            {
                continue;
            }
            let text = std::fs::read_to_string(&path).expect("readable");
            if SchemaMap::parse(&text).is_none() {
                unmapped.push(path.display().to_string());
            }
            checked += 1;
        }
    }
    assert!(checked > 190, "only {checked} files");
    assert!(unmapped.is_empty(), "no map for: {unmapped:#?}");
}
